css:
@media (min-width: 768px) {
  .date-strip { display: flex !important; overflow-x: auto; padding-bottom: 8px; scroll-snap-type: x mandatory; }
  .date-chip { flex: 0 0 84px; scroll-snap-align: start; }
  .date-strip::-webkit-scrollbar { height: 8px; }
  .date-strip::-webkit-scrollbar-track { background: #eef0f3; border-radius: 4px; }
  .date-strip::-webkit-scrollbar-thumb { background: #b7bec8; border-radius: 4px; }
}
